// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testRegression_property() public {
        address newOwner = address(0x123);
        address initialOwner = c.owner();
        vm.prank(address(this));
        c.setOwner(newOwner);
        address finalOwner = c.owner();
        assertTrue(finalOwner != initialOwner, "Owner should have changed after setOwner");
    }
}
